cypress_script:
describe('Date Picker Functionality', () => {
  it('should select a valid date', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').click();
    cy.get('.react-datepicker__day--018').click(); // Assuming this is the correct day
    cy.get('#datePickerMonthYearInput').should('have.value', '07/18/2026');
  });

  it('should not change URL on invalid date selection', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').click();
    cy.get('.react-datepicker__day--outside-month').click(); // Assuming this is an invalid date selection
    cy.url().should('eq', 'https://demoqa.com/date-picker');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Date Picker Functionality', () => {
  test('should select a valid date', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.click('#datePickerMonthYearInput');
    await page.click('.react-datepicker__day--018'); // Assuming this is the correct day
    const dateValue = await page.inputValue('#datePickerMonthYearInput');
    expect(dateValue).toBe('07/18/2026');
  });

  test('should not change URL on invalid date selection', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.click('#datePickerMonthYearInput');
    await page.click('.react-datepicker__day--outside-month'); // Assuming this is an invalid date selection
    expect(page.url()).toBe('https://demoqa.com/date-picker');
  });
});
